import raw from "./data/demo.json";
import type { NoteKey } from "./i18n/en";

export type Outcome = "repair" | "refuse";
export type StageKey = "fail" | "prep" | "diag" | "patch" | "verify" | "run" | "end";
export type StepKind = "log" | "diff" | "fail" | "healed" | "refused";
export type Reason = "ambiguous_target" | "loop_cap_reached" | "guardrail_violation" | "insufficient_evidence";

/** Real, language-neutral data generated by scripts/build_data.py. */
export type ScenarioData = {
  name: string;
  class: string;
  expected: Outcome;
  failing: string;
  spec: string;
  patch: string;
  patchFile: string;
  failure: string;
  pre: { error: string; dom: unknown[] };
};
export const scenarioData = raw as Record<string, ScenarioData>;

export type Step = { stage: StageKey; kind: StepKind; log: string; note?: NoteKey };
type Run = {
  outcome: Outcome;
  reason?: Reason;
  // True only for a run that was actually observed (id-rename: README "Demo", NVIDIA NIM).
  observed?: boolean;
  // Present for scenarios shown in the player; benchmark-only scenarios carry just the outcome.
  steps?: Step[];
};

