export type ScenarioName = keyof typeof RUNS;
/** Scenarios shown in the player, i.e. the ones with steps; only these need translated text. */
export type PlayerName = { [K in ScenarioName]: (typeof RUNS)[K] extends { steps: Step[] } ? K : never }[ScenarioName];
export type PlayerScenario = ScenarioData & Run & { name: PlayerName; steps: Step[] };

export const playerScenarios: PlayerScenario[] = (Object.keys(RUNS) as ScenarioName[]).flatMap((name) => {
  const run: Run = RUNS[name];
  return run.steps ? [{ ...scenarioData[name], ...run, name: name as PlayerName, steps: run.steps }] : [];
});

export type BenchRow = { name: string; class: string; expected: Outcome; actual: Outcome };
export const benchRows: BenchRow[] = (Object.keys(RUNS) as ScenarioName[]).map((name) => ({
  name,
  class: scenarioData[name].class,
  expected: scenarioData[name].expected,
  actual: RUNS[name].outcome,
}));
